sys_script_include.script:
var Cisco_Secure_Access_Poll_Public_Application = Class.create();
Cisco_Secure_Access_Poll_Public_Application.prototype = {
	initialize: function () {
	},

	pollCSA: function () {
		gs.info("[Cisco Secure Access -  GA] STEP 1: Starting PollCiscoSSEAPIuserapp.pollCisco Secure Access()");
		try {
			// STEP 1: Get Bearer token
			gs.info("[Cisco Secure Access -  GA] STEP 2: Fetching Bearer token...");
			var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
			gs.info("[Cisco Secure Access -  GA] STEP 2: Bearer token fetched: " + (token ? "SUCCESS" : "FAILED"));

			// STEP 2: Call Cisco Cisco Secure Access API (Get Application List)
			gs.info("[Cisco Secure Access -  GA] STEP 3: Executing REST Message 'Cisco SSE - MockUser', Method 'Get Discovered Apps'...");
			var r = new sn_ws.RESTMessageV2('Cisco Secure Access Public Application', 'Get Discovered Apps');
			r.setRequestHeader("Authorization", "Bearer " + token);
			r.setRequestHeader("Accept", "application/json");
			var response = r.execute();
			var status = response.getStatusCode();
			gs.info("[Cisco Secure Access -  GA] STEP 3: REST response status: " + status);

			var responseBody = response.getBody();
			gs.info("[Cisco Secure Access -  GA] STEP 3: Raw Response: " + responseBody);

			if (status !== 200) {
				gs.error("[Cisco Secure Access -  GA] ERROR: REST call failed with status " + status);
				throw new Error("REST call failed with status " + status);
			}

			// STEP 3: Parse response
			gs.info("[Cisco Secure Access -  GA] STEP 3: Parsing response...");
			var parsed = JSON.parse(responseBody);
			var csaResources = parsed.items || [];
			gs.info("[Cisco Secure Access -  GA] STEP 3: Total resources fetched from Cisco Secure Access: " + csaResources.length);

			// STEP 4: Build CMDB resource list
			gs.info("[Cisco Secure Access -  GA] STEP 4: Querying CMDB table...");
			var cmdbGR = new GlideRecord('u_cmdb_ci_application');
			cmdbGR.query();

			var cmdbResources = {};
			var cmdbCount = 0;
			while (cmdbGR.next()) {
				var resourceId = cmdbGR.getValue('u_resource_id') || cmdbGR.getValue('name');
				cmdbResources[resourceId] = true;
				cmdbCount++;
			}
			gs.info("[Cisco Secure Access -  GA] STEP 4: Total resources in CMDB: " + cmdbCount);

			// STEP 5: Insert new resources into the local discovered applications table
			gs.info("[Cisco Secure Access -  GA] STEP 5: Inserting new resources into discovered applications table...");
			var inserted = [];

			for (var i = 0; i < csaResources.length; i++) {
				var res = csaResources[i];
				var resourceId = res.resourceId || res.id || res.name;

				// --- Check if resource already exists in CMDB or local table ---
				var exists = cmdbResources[resourceId];

				if (!exists) {
					var localGR = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
					localGR.addQuery('u_app_id', resourceId);
					localGR.query();

					if (localGR.hasNext()) {
						gs.info("[Cisco Secure Access -  GA] STEP 5: Resource already exists in local table: " + resourceId);
						exists = true;
					}
				}

				// --- Insert only if not exists anywhere ---
				if (!exists) {
					var gr = new GlideRecord('u_cisco_sceure_access_discovered_appliaction');
					gr.initialize();
					gr.u_app_id = resourceId;

					// --- Default flags ---
					gr.u_status = "pending";
					gr.u_send_alert = "no";

					// --- Map Cisco Secure Access fields ---
					gr.u_app_name = res.name || "";
					gr.u_category = res.category || "";
					gr.u_label = res.label || "";
					gr.u_weighted_risk = res.weightedRisk || "";
					gr.u_app_type = res.appType || "";
					gr.u_subcategory = res.subcategory || "";
					gr.u_subcategory_content_types = Array.isArray(res.subcategory_content_types) ? res.subcategory_content_types.join(",") : "";
					gr.u_first_detected = res.firstDetected || "";
					gr.u_last_detected = res.lastDetected || "";
					gr.u_discovery_date = new GlideDateTime();
					gr.u_discovered_in = "CSA";

					var sysId = gr.insert();
					gs.info("[Cisco Secure Access -  GA] STEP 5: Inserted resource: " + (res.name || resourceId) + " (sys_id: " + sysId + ")");
					inserted.push(res.name || resourceId);
				} else {
					gs.info("[Cisco Secure Access -  GA] STEP 5: Resource skipped (already exists): " + resourceId);
				}
			}

			if (inserted.length > 0) {
				gs.info("[Cisco Secure Access -  GA] STEP 6: Inserted new discovered applications: " + inserted.join(", "));
			} else {
				gs.info("[Cisco Secure Access -  GA] STEP 6: No new resources to insert.");
			}

			gs.info("[Cisco Secure Access -  GA] STEP 7: PollCiscoSSEAPIuserapp.pollCisco Secure Access() completed.");

		} catch (ex) {
			gs.error('[Cisco Secure Access -  GA] ERROR: Failed to import discovered applications: ' + ex.message);
		}

	},

	type: 'Cisco_Secure_Access_Poll_Public_Application'
};
